import{f as e}from"./jsx-runtime-BZB-tpMt.js";var t=e({default:()=>ee}),ee=JSON.parse(`[{"id":"q-sdoh-1","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Which of these is a social determinant of health?","options":[{"id":"a","text":"The quality and affordability of housing in a neighborhood.","feedback":"Yes: where and how people live shapes health far beyond what happens in a doctor's office.","correct":true},{"id":"b","text":"A person's genes.","feedback":"Genes matter, but they are a biological factor, not a social condition of where people live.","misconception":"sdoh-individual-only"},{"id":"c","text":"One lab test result.","feedback":"A test result is a measurement of health, not a condition that shapes it.","misconception":"sdoh-individual-only"},{"id":"d","text":"The brand of someone's shoes.","feedback":"That is not a condition that systematically shapes health.","misconception":"sdoh-individual-only"}],"explanation":"Social determinants of health are the conditions where people are born, live, learn, work, and play. They shape health more than medical care alone.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-1p","hint":"Think about conditions of daily life, not individual measurements."},{"id":"q-sdoh-1p","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Which of these is a social determinant of health?","options":[{"id":"a","text":"A single blood pressure reading.","feedback":"A reading measures health; it is not a condition of the community.","misconception":"sdoh-individual-only"},{"id":"b","text":"A person's favorite food.","feedback":"Preferences matter less than what food is available and affordable nearby.","misconception":"sdoh-individual-only"},{"id":"c","text":"The result of a coin toss.","feedback":"Chance is not a social condition.","misconception":"sdoh-individual-only"},{"id":"d","text":"Whether a neighborhood has a safe place to be physically active.","feedback":"Right: the built environment is one of the conditions that shape health.","correct":true}],"explanation":"Conditions of everyday life, such as housing, income, safe places to play, and schools, are social determinants.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-1","hint":"Think about conditions of daily life, not individual measurements."},{"id":"q-sdoh-2","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A neighborhood has no safe sidewalks or parks. Which domain of the social determinants of health does this belong to?","options":[{"id":"a","text":"Neighborhood and built environment","feedback":"Yes: sidewalks, parks, and safe streets are part of the built environment.","correct":true},{"id":"b","text":"Education access and quality","feedback":"Education is about schools and learning, not sidewalks or parks.","misconception":"sdoh-domain-mix"},{"id":"c","text":"Economic stability","feedback":"Economic stability is about income, jobs, and housing costs.","misconception":"sdoh-domain-mix"},{"id":"d","text":"Health care access and quality","feedback":"Health care access is about clinics, insurance, and distance to care.","misconception":"sdoh-domain-mix"}],"explanation":"The five domains are economic stability, education access and quality, health care access and quality, neighborhood and built environment, and social and community context.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-2p","hint":"Ask what the problem is mainly about."},{"id":"q-sdoh-2p","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A family spends 60% of its income on rent and often skips meals to pay bills. Which domain of the social determinants of health is this?","options":[{"id":"a","text":"Neighborhood and built environment","feedback":"This family's problem is about money, not sidewalks or parks.","misconception":"sdoh-domain-mix"},{"id":"b","text":"Education access and quality","feedback":"Nothing here is about schooling.","misconception":"sdoh-domain-mix"},{"id":"c","text":"Social and community context","feedback":"That domain is about relationships, trust, and discrimination.","misconception":"sdoh-domain-mix"},{"id":"d","text":"Economic stability","feedback":"Right: income, jobs, and the cost of housing and food are economic stability.","correct":true}],"explanation":"Match the problem to the domain: money, schools, care, place, or community.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-2","hint":"Ask what the problem is mainly about."},{"id":"q-sdoh-3","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Two Riverton neighborhoods 3 miles apart have a 12-year gap in life expectancy. What best explains it?","options":[{"id":"a","text":"Differences in conditions such as income, food access, housing, air quality, and access to care.","feedback":"Yes: these conditions add up over a lifetime and differ greatly between nearby neighborhoods.","correct":true},{"id":"b","text":"People in one neighborhood simply make worse choices.","feedback":"Choices are shaped by what is available. Blaming people hides the conditions.","misconception":"sdoh-individual-only"},{"id":"c","text":"It is only due to genes.","feedback":"Genes cannot explain large differences between nearby neighborhoods.","misconception":"sdoh-individual-only"},{"id":"d","text":"It is random.","feedback":"Large, consistent gaps follow patterns in conditions.","misconception":"sdoh-individual-only"}],"explanation":"Differences in conditions of daily life explain much of the gap in health between neighborhoods.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-3p","hint":"What is different about where these people live?"},{"id":"q-sdoh-3p","module":"city","concept":"sdoh","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Children living near a highway have triple the asthma rate of children far from it. What best explains this?","options":[{"id":"a","text":"Their families care less.","feedback":"That blames families. The environment is a likelier cause.","misconception":"sdoh-individual-only"},{"id":"b","text":"Asthma is only inherited.","feedback":"Genes matter but cannot explain a threefold difference by location.","misconception":"sdoh-individual-only"},{"id":"c","text":"It is a coincidence.","feedback":"A pattern this strong is unlikely to be chance.","misconception":"sdoh-individual-only"},{"id":"d","text":"Traffic pollution and older housing near the highway, which are conditions of the place.","feedback":"Right: a place-based exposure, not a personal failing.","correct":true}],"explanation":"Large gaps between nearby places point to differences in conditions, not in people's character.","context":"lesson:city-sdoh","seconds":40,"parallel":"q-sdoh-3","hint":"What is different about where these people live?"},{"id":"q-ud-1","module":"city","concept":"upstream-downstream","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Which action is the most upstream?","options":[{"id":"a","text":"Prescribing an inhaler after an attack.","feedback":"Treatment is important but downstream.","misconception":"ud-downstream-confuse"},{"id":"b","text":"Opening a new hospital burn unit.","feedback":"Hospital care responds to harm that has already happened.","misconception":"ud-downstream-confuse"},{"id":"c","text":"Building affordable housing so fewer families face unstable housing.","feedback":"Yes: upstream actions change the conditions that cause problems in the first place.","correct":true},{"id":"d","text":"Treating asthma attacks in the emergency room.","feedback":"That is downstream: it responds after someone is already sick.","misconception":"ud-downstream-confuse"}],"explanation":"Think of a river. Upstream actions fix what pollutes the water. Downstream actions rescue people already in the current.","context":"lesson:city-upstream","seconds":40,"parallel":"q-ud-1p","hint":"Which action prevents the problem rather than responding to it?"},{"id":"q-ud-1p","module":"city","concept":"upstream-downstream","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Which action is the most upstream?","options":[{"id":"a","text":"Training ER staff in asthma care.","feedback":"Helpful, but still downstream.","misconception":"ud-downstream-confuse"},{"id":"b","text":"Requiring cleaner emissions from a factory so fewer children develop asthma.","feedback":"Right: it prevents the exposure that causes illness.","correct":true},{"id":"c","text":"Treating children in the ER during asthma attacks.","feedback":"That responds after illness.","misconception":"ud-downstream-confuse"},{"id":"d","text":"Buying more ambulances.","feedback":"Ambulances respond to emergencies.","misconception":"ud-downstream-confuse"}],"explanation":"Upstream = change the causes. Downstream = respond to the results.","context":"lesson:city-upstream","seconds":40,"parallel":"q-ud-1","hint":"Which action prevents the problem rather than responding to it?"},{"id":"q-pl-1","module":"city","concept":"prevention-levels","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A community offers free blood pressure screenings at a street fair. What level of prevention is this?","options":[{"id":"a","text":"Tertiary prevention: managing an existing condition.","feedback":"Tertiary prevention limits harm in people who already have a disease.","misconception":"pl-levels"},{"id":"b","text":"It is not prevention.","feedback":"Screening is a classic form of prevention.","misconception":"pl-levels"},{"id":"c","text":"Secondary prevention: finding a problem early.","feedback":"Yes: screening catches disease early, when treatment works best.","correct":true},{"id":"d","text":"Primary prevention: stopping a problem before it starts.","feedback":"Primary prevention keeps people from getting the condition, for example with vaccines.","misconception":"pl-levels"}],"explanation":"Primary prevention stops a problem before it starts, secondary catches it early, and tertiary limits the harm of an existing problem.","context":"lesson:city-upstream","seconds":40,"parallel":"q-pl-1p","hint":"Is the illness absent, just starting, or already established?"},{"id":"q-pl-1p","module":"city","concept":"prevention-levels","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A clinic offers mammograms to catch breast cancer early. What level of prevention is this?","options":[{"id":"a","text":"Not prevention.","feedback":"Screening is secondary prevention.","misconception":"pl-levels"},{"id":"b","text":"Secondary prevention: early detection.","feedback":"Right: screening finds disease early.","correct":true},{"id":"c","text":"Primary prevention.","feedback":"Primary stops disease from starting.","misconception":"pl-levels"},{"id":"d","text":"Tertiary prevention.","feedback":"Tertiary manages disease already diagnosed.","misconception":"pl-levels"}],"explanation":"Screening means finding disease early: secondary prevention.","context":"lesson:city-upstream","seconds":40,"parallel":"q-pl-1","hint":"Is the illness absent, just starting, or already established?"},{"id":"q-pl-2","module":"city","concept":"prevention-levels","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A vaccination clinic gives flu shots before flu season. What level of prevention is this?","options":[{"id":"a","text":"Tertiary prevention.","feedback":"Tertiary manages existing disease.","misconception":"pl-levels"},{"id":"b","text":"Treatment only.","feedback":"Vaccination prevents illness.","misconception":"pl-levels"},{"id":"c","text":"Primary prevention: stopping illness before it starts.","feedback":"Yes: vaccines prevent infection in the first place.","correct":true},{"id":"d","text":"Secondary prevention.","feedback":"Secondary finds disease early.","misconception":"pl-levels"}],"explanation":"Vaccines are the classic example of primary prevention.","context":"lesson:city-upstream","seconds":40,"parallel":"q-pl-2p","hint":"Has anyone become ill yet?"},{"id":"q-pl-2p","module":"city","concept":"prevention-levels","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A city adds fluoride to drinking water to prevent cavities. What level of prevention is this?","options":[{"id":"a","text":"It is treatment.","feedback":"It prevents rather than treats.","misconception":"pl-levels"},{"id":"b","text":"Primary prevention: stopping problems before they begin.","feedback":"Right: it prevents cavities from forming.","correct":true},{"id":"c","text":"Secondary prevention.","feedback":"Nobody has been screened here.","misconception":"pl-levels"},{"id":"d","text":"Tertiary prevention.","feedback":"It is not managing existing disease.","misconception":"pl-levels"}],"explanation":"If it stops disease before it starts, it is primary prevention.","context":"lesson:city-upstream","seconds":40,"parallel":"q-pl-2","hint":"Has anyone become ill yet?"},{"id":"q-eq-1","module":"city","concept":"equity-equality","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A city gives every neighborhood the same $1 million for clinics, whatever its needs. This is an example of:","options":[{"id":"a","text":"Both equity and equality, since they mean the same thing.","feedback":"They are different ideas, and the difference matters for health gaps.","misconception":"eq-same-thing"},{"id":"b","text":"Neither: it is random.","feedback":"It follows a clear rule, equal shares.","misconception":"eq-same-thing"},{"id":"c","text":"Equality: the same for everyone, which may not close gaps.","feedback":"Yes: equal shares can leave the neighborhoods with the greatest needs behind.","correct":true},{"id":"d","text":"Equity: giving each group what it needs.","feedback":"Equity would give more to the places with the greatest needs.","misconception":"eq-same-thing"}],"explanation":"Equality means everyone gets the same. Equity means everyone gets what they need to have a fair chance at good health.","context":"lesson:city-equity","seconds":40,"parallel":"q-eq-1p","hint":"Does everyone start at the same place?"},{"id":"q-eq-1p","module":"city","concept":"equity-equality","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A school gives every student the same size shoes. This is an example of:","options":[{"id":"a","text":"Neither.","feedback":"Giving everyone the same item is equality.","misconception":"eq-same-thing"},{"id":"b","text":"Equality: identical treatment, which does not fit everyone.","feedback":"Right: the same shoes do not help students whose feet are different sizes.","correct":true},{"id":"c","text":"Equity.","feedback":"Equity would give each student shoes that fit.","misconception":"eq-same-thing"},{"id":"d","text":"Equity and equality together.","feedback":"They differ: equal means the same, equitable means fair given needs.","misconception":"eq-same-thing"}],"explanation":"Equal treatment can still leave gaps if people start from different places.","context":"lesson:city-equity","seconds":40,"parallel":"q-eq-1","hint":"Does everyone start at the same place?"},{"id":"q-eq-2","module":"city","concept":"equity-equality","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A health department wants to close the life expectancy gap. Which approach is most equitable?","options":[{"id":"a","text":"Funding whichever neighborhood asks first.","feedback":"That rewards who can ask, not who needs help most.","misconception":"eq-squeaky"},{"id":"b","text":"Funding the wealthiest neighborhood, since it will use the money well.","feedback":"That widens the gap.","misconception":"eq-same-thing"},{"id":"c","text":"Directing more resources to neighborhoods with the worst outcomes.","feedback":"Yes: closing a gap means giving more where the need and the gap are greatest.","correct":true},{"id":"d","text":"Splitting funds evenly across neighborhoods.","feedback":"That is equality. It leaves the starting gap largely in place.","misconception":"eq-same-thing"}],"explanation":"Equitable approaches direct more to where the gap and need are greatest.","context":"lesson:city-equity","seconds":40,"parallel":"q-eq-2p","hint":"Where is the need greatest?"},{"id":"q-eq-2p","module":"city","concept":"equity-equality","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Flood-prevention money is limited. Which approach is most equitable?","options":[{"id":"a","text":"Funding only the cheapest projects.","feedback":"Cost alone says nothing about fairness.","misconception":"eq-same-thing"},{"id":"b","text":"Prioritizing neighborhoods with the highest flood risk and the fewest resources to recover.","feedback":"Right: focus on greatest need and least capacity.","correct":true},{"id":"c","text":"Giving every neighborhood the same amount.","feedback":"Equal shares ignore different risks.","misconception":"eq-same-thing"},{"id":"d","text":"Funding whoever lobbies the loudest.","feedback":"Loud is not the same as needy.","misconception":"eq-squeaky"}],"explanation":"Equity looks at need and outcomes, not just equal shares.","context":"lesson:city-equity","seconds":40,"parallel":"q-eq-2","hint":"Where is the need greatest?"},{"id":"q-city-cer","module":"city","concept":"sdoh","type":"cer","difficulty":3,"trigger":"sim-conclusion","context":"sim:city","required":true,"prompt":"Write your conclusion for Close the Gap. Claim: did your plan narrow the gap, and by how much? Evidence: cite numbers from your charts, snapshots, or the Why did this change? panel. Reasoning: explain the mechanism (which determinants and behaviors changed), why outcomes took years, whether your plan was upstream or downstream, whether it was equitable, and one limitation of this model.","explanation":"A strong conclusion states the result with numbers, traces cause and effect through determinants and behaviors, notes lags and equity, and names what the simplified model leaves out.","rubric":[{"id":"claim","criterion":"States whether the gap narrowed and by how much."},{"id":"evidence","criterion":"Cites specific numbers or trends from the city."},{"id":"mechanism","criterion":"Explains the causal chain: intervention, then conditions, then behaviors, then outcomes, including lags."},{"id":"equity","criterion":"Discusses upstream vs. downstream or equity, and who benefited."},{"id":"limits","criterion":"Names a limitation of the model."}],"sampleAnswer":"Claim: My plan narrowed the gap between Hillcrest and Eastside by about 2.6 years over ten years. Evidence: In the Trends chart, Eastside life expectancy rose from 69.7 to 72.3, and preventable ER visits fell from 142 to about 100 per 1,000. The Why panel showed most of the ER drop came from the clinic and the community health workers. Reasoning: The clinic raised healthcare access, which increased preventive care and cut ER use within two years, while the supermarket and nutrition education moved diet slowly, so obesity barely changed. Most of my spending was upstream, on conditions like food, housing, and care access, which is why life expectancy kept rising late in the run, because it moves slowest. It was equitable because I spent almost everything in Eastside, and the model showed little citywide change from the same money in Hillcrest. One limitation is that the model is a simplified teaching tool with invented numbers, so the real effects would differ."}]`),te=e({default:()=>n}),n=JSON.parse(`[{"id":"q-xdm-1","module":"crossroads","concept":"decision-model","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A commission has to decide what to do with a vacant lot. Which step of the community health decision model comes first?","options":[{"id":"a","text":"Consider options: draw up buildings.","feedback":"Options come after you know the problem and have listened to the community.","misconception":"dm-skip-ahead"},{"id":"b","text":"Define the problem with data: who is affected, and how large is the gap?","feedback":"Yes: start by understanding the problem with evidence before choosing a solution.","correct":true},{"id":"c","text":"Decide: pick the proposal that sounds best.","feedback":"Deciding is step 6. Jumping there skips understanding the problem and the people affected.","misconception":"dm-skip-ahead"},{"id":"d","text":"Evaluate: see how it worked.","feedback":"Evaluation is the last step, after a decision is made and carried out.","misconception":"dm-skip-ahead"}],"explanation":"The decision model runs: define the problem with data, identify who is affected, listen, consider evidence-based options, weigh equity and trade-offs, decide, and evaluate.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-xdm-1p","hint":"Think about what you need to know before you can choose."},{"id":"q-xdm-1p","module":"crossroads","concept":"decision-model","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A school board is worried about rising absences. What should it do first in the community health decision model?","options":[{"id":"a","text":"Define the problem with data: how many absences, among whom, and why?","feedback":"Right: describe the problem and who is affected before picking solutions.","correct":true},{"id":"b","text":"Buy a new attendance app.","feedback":"That jumps to a solution before the problem is understood.","misconception":"dm-skip-ahead"},{"id":"c","text":"Vote on a new policy.","feedback":"Deciding comes after defining, listening, and weighing options.","misconception":"dm-skip-ahead"},{"id":"d","text":"Evaluate last year's program.","feedback":"Evaluation follows a decision.","misconception":"dm-skip-ahead"}],"explanation":"Always start with the problem and the people affected, not the solution.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-xdm-1","hint":"Think about what you need to know before you can choose."},{"id":"q-stk-1","module":"crossroads","concept":"stakeholders","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"In a decision about a new clinic, which people are stakeholders?","options":[{"id":"a","text":"Only residents who live next door.","feedback":"People who use or pay for it, or who live farther away, can be stakeholders as well.","misconception":"stk-only-decisionmakers"},{"id":"b","text":"Anyone affected by or able to influence the decision: patients, nearby residents, store owners, clinic staff, and funders.","feedback":"Yes: stakeholders include those who benefit, those who bear costs, and those with power or resources.","correct":true},{"id":"c","text":"Only the people who will vote on it.","feedback":"Voters are stakeholders, but so are people who live with the results.","misconception":"stk-only-decisionmakers"},{"id":"d","text":"Only the people who support it.","feedback":"Opponents and skeptics are stakeholders too, and often know the risks.","misconception":"stk-only-supporters"}],"explanation":"A stakeholder is anyone affected by a decision or able to influence it. Mapping them shows who benefits, who bears costs, and who is left out.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-stk-1p","hint":"Think beyond the people at the table."},{"id":"q-stk-1p","module":"crossroads","concept":"stakeholders","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A city plans to close a bus line. Who is a stakeholder?","options":[{"id":"a","text":"Riders who depend on it, nearby businesses, drivers, and the transit agency.","feedback":"Right: those affected and those with a role are stakeholders.","correct":true},{"id":"b","text":"Only the transit agency, since it makes the decision.","feedback":"Riders feel the effects directly and are stakeholders.","misconception":"stk-only-decisionmakers"},{"id":"c","text":"Only riders who complain.","feedback":"People who are affected quietly count too.","misconception":"stk-only-supporters"},{"id":"d","text":"Nobody outside city hall.","feedback":"Many groups outside city hall are affected.","misconception":"stk-only-decisionmakers"}],"explanation":"Stakeholder analysis asks who gains, who pays, and who is missing.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-stk-1","hint":"Think beyond the people at the table."},{"id":"q-eng-1","module":"crossroads","concept":"engagement-equity","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A health department holds its only listening session at 6 p.m. on a weekday downtown. Why might this miss the people most affected?","options":[{"id":"a","text":"Because only experts can understand the issue.","feedback":"Residents hold important knowledge about their own lives.","misconception":"eng-everyone-can"},{"id":"b","text":"People who work evenings, lack transportation, or need childcare may not be able to attend.","feedback":"Yes: the people most affected are often least able to attend, so the format shapes who is heard.","correct":true},{"id":"c","text":"Because people who care will always find a way to come.","feedback":"Barriers like work, childcare, and transportation keep many people away even if they care.","misconception":"eng-everyone-can"},{"id":"d","text":"Because meetings do not work as a way to hear from people.","feedback":"Meetings can work well when held where and when people can attend.","misconception":"eng-everyone-can"}],"explanation":"Equity of participation means removing barriers so the people most affected can take part: time, place, childcare, language, and transportation.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-eng-1p","hint":"Think about what keeps people from attending."},{"id":"q-eng-1p","module":"crossroads","concept":"engagement-equity","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A county wants feedback from older adults on a new bus route. Which plan best supports equity of participation?","options":[{"id":"a","text":"Meet at senior centers during the day, offer rides, large-print materials, and a phone line.","feedback":"Right: remove barriers so the people most affected can take part.","correct":true},{"id":"b","text":"Post a link to an online form.","feedback":"Many older adults have limited access to or comfort with online tools.","misconception":"eng-everyone-can"},{"id":"c","text":"Hold one evening meeting at the county office.","feedback":"Evening hours and transportation can be barriers.","misconception":"eng-everyone-can"},{"id":"d","text":"Ask only the people who already attend every meeting.","feedback":"The usual voices do not represent everyone.","misconception":"eng-everyone-can"}],"explanation":"How and when you ask decides who answers.","context":"lesson:xr-decision-stakeholders","seconds":40,"parallel":"q-eng-1","hint":"Think about what keeps people from attending."},{"id":"q-mis-1","module":"crossroads","concept":"misinformation","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"You see a viral post claiming a public health notice is fake. What does 'lateral reading' mean?","options":[{"id":"a","text":"Ask the person who posted it if it is true.","feedback":"The poster has an interest in saying yes. Check independent sources instead.","misconception":"mis-vertical"},{"id":"b","text":"Leave the post and open other tabs to see what trusted sources say about the claim and its source.","feedback":"Yes: checking what others say about the source is faster and more reliable than studying the post itself.","correct":true},{"id":"c","text":"Read the post closely from top to bottom.","feedback":"Reading the post more closely cannot tell you whether it is trustworthy.","misconception":"mis-vertical"},{"id":"d","text":"Count how many likes and shares it has.","feedback":"Popularity does not show whether something is true.","misconception":"mis-popular"}],"explanation":"Lateral reading: leave the page and check what other reliable sources say about the claim and the source.","context":"lesson:xr-misinfo","seconds":40,"parallel":"q-mis-1p","hint":"Ask: who else says this?"},{"id":"q-mis-1p","module":"crossroads","concept":"misinformation","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A message says a local clinic is spreading illness. Which step is lateral reading?","options":[{"id":"a","text":"Search the clinic's name and look at what health departments and independent news sites say.","feedback":"Right: step away from the message and check outside sources.","correct":true},{"id":"b","text":"Look at how many people shared it.","feedback":"Shares measure spread, not accuracy.","misconception":"mis-popular"},{"id":"c","text":"Read the message again looking for typos.","feedback":"Typos do not show whether the claim is true.","misconception":"mis-vertical"},{"id":"d","text":"Trust it because it came from a friend.","feedback":"Friends can pass on mistakes in good faith.","misconception":"mis-popular"}],"explanation":"To judge a source, look at what others say about it, not only what it says about itself.","context":"lesson:xr-misinfo","seconds":40,"parallel":"q-mis-1","hint":"Ask: who else says this?"},{"id":"q-tm-1","module":"crossroads","concept":"trusted-messengers","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Why might a neighborhood pastor or respected elder be better than a city agency at getting people to follow a health notice?","options":[{"id":"a","text":"Because the agency does not need to communicate.","feedback":"Agencies still provide the facts; messengers help people believe and act.","misconception":"tm-agency-enough"},{"id":"b","text":"Because messages are always louder from one person.","feedback":"Reach matters, but trust is what changes behavior.","misconception":"tm-expert-only"},{"id":"c","text":"People tend to trust messengers they know and who share their community and values.","feedback":"Yes: trusted messengers carry credibility that an official announcement may lack.","correct":true},{"id":"d","text":"Because pastors know more about science.","feedback":"The advantage is trust and relationships, not expertise.","misconception":"tm-expert-only"}],"explanation":"Trusted messengers, such as faith leaders, elders, and bilingual neighbors, make health messages credible because people believe voices they know.","context":"lesson:xr-misinfo","seconds":40,"parallel":"q-tm-1p","hint":"Think about who people already believe."},{"id":"q-tm-1p","module":"crossroads","concept":"trusted-messengers","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A health department needs more families to get a flu shot. Which approach best uses a trusted messenger?","options":[{"id":"a","text":"Have a stranger read the facts aloud.","feedback":"Without trust, facts do not change behavior.","misconception":"tm-expert-only"},{"id":"b","text":"Ask a respected local coach to explain why they vaccinate their own family, with the department's facts.","feedback":"Right: a trusted voice combined with accurate information.","correct":true},{"id":"c","text":"Mail a flyer to every address.","feedback":"Flyers alone often fail to build trust.","misconception":"tm-agency-enough"},{"id":"d","text":"Post one announcement in English.","feedback":"One language and one channel miss many families.","misconception":"tm-agency-enough"}],"explanation":"Credibility comes from trust and shared experience as well as accuracy.","context":"lesson:xr-misinfo","seconds":40,"parallel":"q-tm-1","hint":"Think about who people already believe."},{"id":"q-xr-data","module":"crossroads","concept":"evidence-lived","type":"mc","difficulty":1,"trigger":"sim-data","prompt":"Eastside's childhood asthma rate is 17.8% and Hillcrest's is 6.5%. What is the best way to read this gap?","options":[{"id":"a","text":"Eastside families care less about their children's health.","feedback":"A gap in rates reflects conditions, not caring. Blaming people hides the causes.","misconception":"xr-blame"},{"id":"b","text":"It is only a 11 point difference, which is small.","feedback":"11 percentage points is large when it is nearly triple the rate.","misconception":"xr-small-gap"},{"id":"c","text":"The data cannot be trusted because it is a single number.","feedback":"A rate comparing two places is meaningful and can guide action.","misconception":"xr-small-gap"},{"id":"d","text":"Eastside's rate is nearly three times as high, which points to conditions in Eastside (air, housing) worth investigating.","feedback":"Yes: comparing the rates shows a large gap, and a large gap calls for looking at conditions, not blaming people.","correct":true}],"explanation":"Comparing rates between places reveals gaps. Large gaps point to conditions that can change.","context":"sim:crossroads","seconds":40,"hint":"Divide one rate by the other."},{"id":"q-xr-evidence","module":"crossroads","concept":"evidence-lived","type":"mc","difficulty":1,"trigger":"sim-evidence","prompt":"Residents tell you they need a hospital, but the data show that most Eastside ER visits are for care a nearby clinic could provide. How should you weigh these?","options":[{"id":"a","text":"Ignore the residents because data is always right.","feedback":"Lived experience is evidence about needs, trust, and what people will use.","misconception":"xr-data-only"},{"id":"b","text":"Ignore the data because residents know best.","feedback":"Data can show patterns that no one person sees.","misconception":"xr-voice-only"},{"id":"c","text":"Build what the loudest person asks for.","feedback":"Volume is not evidence.","misconception":"xr-voice-only"},{"id":"d","text":"Treat both as evidence: ask why residents want a hospital, and test whether easier access to primary care would solve what they describe.","feedback":"Yes: lived experience and data both count, and the conflict is a clue about what people actually need.","correct":true}],"explanation":"Lived experience and data are both evidence. When they disagree, treat the gap as something to explain.","context":"sim:crossroads","seconds":40,"hint":"Neither source automatically wins."},{"id":"q-xr-dvo","module":"crossroads","concept":"decision-vs-outcome","type":"mc","difficulty":1,"trigger":"sim-dvo","prompt":"Your proposal was well researched, but bad luck made the projected results worse than typical. How should you judge the decision?","options":[{"id":"a","text":"The reasoning and process were sound even though the outcome was unlucky. Judge decisions by the information and reasoning at the time.","feedback":"Yes: good decisions can have bad outcomes, and bad decisions can get lucky.","correct":true},{"id":"b","text":"The decision was bad because the outcome was bad.","feedback":"Outcomes include luck. A good process can still meet bad luck.","misconception":"dvo-outcome-only"},{"id":"c","text":"Outcomes never matter.","feedback":"Outcomes matter for learning, but they are not the only measure of decision quality.","misconception":"dvo-outcome-only"},{"id":"d","text":"There is no way to tell skill from luck.","feedback":"Comparing to what was typical helps separate them.","misconception":"dvo-outcome-only"}],"explanation":"Decision quality is about process and reasoning. Outcomes also depend on chance.","context":"sim:crossroads","seconds":40,"hint":"Think about what you knew when you decided."},{"id":"q-xr-trade","module":"crossroads","concept":"tradeoffs","type":"mc","difficulty":1,"trigger":"sim-tradeoff","prompt":"Accepting the developer's extra $2 million would build more. What is the opportunity cost?","options":[{"id":"a","text":"The only cost is the price of the buildings.","feedback":"Costs include what you give up and who bears them.","misconception":"tr-no-cost"},{"id":"b","text":"Opportunity cost means the cost of opportunities.","feedback":"It means what you give up by choosing one option over another.","misconception":"tr-no-cost"},{"id":"c","text":"What you give up by choosing it: for example, less control over who lives nearby and a higher risk of displacement.","feedback":"Yes: opportunity cost is the value of the best option you did not choose.","correct":true},{"id":"d","text":"There is no cost because the money is free.","feedback":"Money from a deal usually comes with conditions that have costs.","misconception":"tr-no-cost"}],"explanation":"Every choice has an opportunity cost: the next-best option you give up.","context":"sim:crossroads","seconds":40,"hint":"Ask: what do I lose by choosing this?"},{"id":"q-xr-th-cer","module":"crossroads","concept":"decision-vs-outcome","type":"cer","difficulty":3,"trigger":"sim-reflect","context":"sim:crossroads","required":true,"prompt":"Reflect on the Town Hall. Claim: how would you judge the quality of your decision, separate from how it turned out? Evidence: what data or voices shaped it? Reasoning: whose voice most changed your thinking, whose was missing, and did your decision advance health equity?","explanation":"A strong reflection separates reasoning from results, cites specific evidence, names missing voices, and uses the data to judge equity.","rubric":[{"id":"claim","criterion":"Judges decision quality separately from the outcome."},{"id":"evidence","criterion":"Cites specific data or stakeholder input."},{"id":"voice","criterion":"Names whose voice changed your thinking and whose was missing."},{"id":"equity","criterion":"Uses the data to judge whether the decision narrowed or widened the health gap."}],"sampleAnswer":"Claim: I think my decision was good even though the outcome was only average, because my reasoning matched what I knew. I chose the Saturday session so families like Ms. Alvarez could attend, and I used the data showing Eastside's preventable ER visits are nearly four times Hillcrest's. Evidence: Pastor Bell's concern about rents changed my mind about the developer's offer, so I declined it and added protections. Reasoning: The projection shows the health gap narrowing a little, and few residents were displaced, which suggests it advanced equity. One voice I did not hear was the developer's full financial constraints, and I could have asked more residents about the housing option. The result was somewhat lower than typical because of bad luck, not because of a flaw in the process."},{"id":"q-xr-rm-cer","module":"crossroads","concept":"trusted-messengers","type":"cer","difficulty":3,"trigger":"sim-reflect","context":"sim:crossroads","required":true,"prompt":"Short reflection. Claim: which of your choices did the most to change how many people followed the guidance? Evidence: what changed on the epidemic curve? Reasoning: why does that approach work with this community?","explanation":"Strong answers connect a specific choice to a specific change and explain it with trust, language, or source credibility.","rubric":[{"id":"claim","criterion":"Names a specific choice."},{"id":"evidence","criterion":"Uses the change in cases or compliance."},{"id":"reasoning","criterion":"Explains with trust, a trusted messenger, language access, or verification."}],"sampleAnswer":"Claim: Asking Pastor Bell to share the notice did the most. Evidence: more residents followed the guidance, and the projected cases fell by about a third compared with doing nothing. Reasoning: People in this neighborhood trust Pastor Bell more than a city announcement, so her message carried credibility. Posting in two languages also reached families who might have missed it."}]`),ne=e({default:()=>re}),re=JSON.parse(`[{"id":"q-coi-1","module":"lab","concept":"chain-of-infection","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A food worker with a stomach bug handles lettuce without washing their hands, and customers who eat it get sick. Which link in the chain of infection is the contaminated lettuce?","options":[{"id":"a","text":"Portal of exit","feedback":"The portal of exit is how the germ leaves the worker, such as through hands or stool.","misconception":"coi-exit-confusion"},{"id":"b","text":"Vehicle (how the germ travels from the reservoir to a new host)","feedback":"Right: the lettuce carries the germ from the sick worker to customers. Stopping the vehicle breaks the chain.","correct":true},{"id":"c","text":"Reservoir (where the germ normally lives)","feedback":"The reservoir here is the sick worker. The lettuce is how the germ moves.","misconception":"coi-reservoir-vehicle"},{"id":"d","text":"Susceptible host","feedback":"The customers are the susceptible hosts. The lettuce is not a person.","misconception":"coi-host-confusion"}],"explanation":"The chain of infection has six links: germ, reservoir, portal of exit, mode of transmission (the vehicle or route), portal of entry, and susceptible host. Break any link and the chain stops.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-coi-1p","hint":"Ask: what moves the germ between people?"},{"id":"q-coi-1p","module":"lab","concept":"chain-of-infection","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A public pool's water carries a germ from one swimmer's illness to many other swimmers. Which link in the chain of infection is the pool water?","options":[{"id":"a","text":"Vehicle (how the germ travels to a new host)","feedback":"Yes: the pool water carries the germ from the reservoir to new hosts.","correct":true},{"id":"b","text":"Reservoir","feedback":"The reservoir is the original source, such as a sick swimmer. The water carries the germ onward.","misconception":"coi-reservoir-vehicle"},{"id":"c","text":"Susceptible host","feedback":"The swimmers who get sick are the hosts.","misconception":"coi-host-confusion"},{"id":"d","text":"Portal of entry","feedback":"The portal of entry is how the germ gets into the new host's body, such as swallowing water.","misconception":"coi-exit-confusion"}],"explanation":"The pool water is the vehicle: it carries the germ from where it came from to new hosts. Public health acts on whichever link is easiest to break.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-coi-1","hint":"Ask: what moves the germ between people?"},{"id":"q-surv-1","module":"lab","concept":"surveillance","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Riverton's lab reports show 40 confirmed stomach-illness cases this week. Why are there probably many more people who are actually sick?","options":[{"id":"a","text":"Only a fraction of sick people seek care, get tested, and are reported, so reported cases are the tip of the iceberg.","feedback":"Yes: this is the surveillance pyramid. Many ill people stay home, are never tested, or are never reported.","correct":true},{"id":"b","text":"The lab made counting errors.","feedback":"Lab errors exist but are small. The big gap comes from people never being tested.","misconception":"surv-lab-error"},{"id":"c","text":"Everyone who gets sick is reported, so 40 is the true number.","feedback":"Reports only count people who reach the system. Most illness goes uncounted.","misconception":"surv-all-counted"},{"id":"d","text":"The extra cases are people who were not really sick.","feedback":"Nothing in the data says that. The undercount is real illness that never reached a lab.","misconception":"surv-lab-error"}],"explanation":"Surveillance systems see only cases that move up the pyramid: illness, then care, then testing, then reporting. Each step loses people.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-surv-1p","hint":"Think about how many sick people actually get tested."},{"id":"q-surv-1p","module":"lab","concept":"surveillance","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A county reports 25 confirmed cases of a stomach bug. A survey of households finds that about 600 residents had the same symptoms. What best explains the difference?","options":[{"id":"a","text":"Households exaggerate their symptoms.","feedback":"Surveys have error, but a 24-fold gap is mostly explained by who reaches the testing system.","misconception":"surv-lab-error"},{"id":"b","text":"Surveillance counts every case, so the survey must be wrong.","feedback":"Surveillance systems know they miss cases; they are built to detect trends, not count every illness.","misconception":"surv-all-counted"},{"id":"c","text":"Cases reported are always larger than true illness.","feedback":"Reported cases are almost always smaller than true illness.","misconception":"surv-all-counted"},{"id":"d","text":"Most ill people never see a doctor or get tested, so reports count only part of the illness.","feedback":"Right: underreporting is normal in surveillance, which is why investigators add active case finding.","correct":true}],"explanation":"Reported counts are a small, delayed sample of the true illness. That is why active case finding exists.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-surv-1","hint":"Think about how many sick people actually get tested."},{"id":"q-surv-2","module":"lab","concept":"surveillance","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Why do surveillance reports often lag several days behind when people actually got sick?","options":[{"id":"a","text":"Care-seeking, lab testing, and paperwork all take time before a case is reported.","feedback":"Yes: the delay is built in, so the newest days look artificially low on the report.","correct":true},{"id":"b","text":"People wait to get sick until the health department asks them to.","feedback":"Illness starts on its own schedule. Reporting is what lags.","misconception":"surv-delay-wrong"},{"id":"c","text":"Reports are only sent once a month by law.","feedback":"Many systems report daily or weekly. The delay comes from the process, not the calendar.","misconception":"surv-delay-wrong"},{"id":"d","text":"Delays happen only when there is an error.","feedback":"Delay is normal, even when everything works.","misconception":"surv-delay-wrong"}],"explanation":"There is a lag between onset and report. The newest days on a surveillance chart look low until cases are reported.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-surv-2p","hint":"Think about how long a lab result takes."},{"id":"q-surv-2p","module":"lab","concept":"surveillance","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A health department sees that reported cases fell sharply on the most recent two days of its chart. What should an investigator suspect first?","options":[{"id":"a","text":"The outbreak has ended.","feedback":"It might have, but a drop in the last days is expected from lag alone.","misconception":"surv-delay-wrong"},{"id":"b","text":"People stopped getting sick because of media coverage.","feedback":"Possible, but check reporting delay before drawing that conclusion.","misconception":"surv-delay-wrong"},{"id":"c","text":"The lab is hiding cases.","feedback":"Nothing suggests that. Lag is the usual cause.","misconception":"surv-delay-wrong"},{"id":"d","text":"Reporting delay: the latest days are incomplete because not all cases have been reported yet.","feedback":"Right: recent days often fill in later. Do not assume the outbreak is over.","correct":true}],"explanation":"A drop at the end of a surveillance chart is often just reporting delay.","context":"lesson:lab-chain-surveillance","seconds":40,"parallel":"q-surv-2","hint":"Think about how long a lab result takes."},{"id":"q-cd-1","module":"lab","concept":"case-definition","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"An investigator defines a case as 'anyone in Riverton with any symptom since last month.' What is the main problem?","options":[{"id":"a","text":"It has no problem: more cases are always better.","feedback":"More is not better. Non-cases dilute the signal and hide the true exposure.","misconception":"cd-more-better"},{"id":"b","text":"It leaves out time, but nothing else.","feedback":"Time is missing, but so are place, person, and a specific symptom set.","misconception":"cd-more-better"},{"id":"c","text":"It is too broad: it counts many people with colds or other illnesses (low specificity).","feedback":"Yes: a broad definition sweeps in non-cases and makes it hard to see what the outbreak really is.","correct":true},{"id":"d","text":"It is too narrow: it will miss real cases.","feedback":"This definition is very inclusive, so it catches nearly everyone. The problem is too many false cases.","misconception":"cd-narrow-broad"}],"explanation":"A case definition uses person, place, time, and clinical criteria. Sensitivity is catching true cases; specificity is excluding non-cases. Early on, investigators use a broader definition.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-cd-1p","hint":"Ask: who would this definition leave out, or let in by mistake?"},{"id":"q-cd-1p","module":"lab","concept":"case-definition","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A definition says 'a case must have diarrhea, vomiting, fever, and a headache, and live in one neighborhood.' What is the likely result?","options":[{"id":"a","text":"It cannot be evaluated.","feedback":"You can evaluate it by checking how many true cases it catches (sensitivity).","misconception":"cd-more-better"},{"id":"b","text":"It is too narrow: it will miss many true cases (low sensitivity).","feedback":"Right: requiring every symptom and one place excludes real cases.","correct":true},{"id":"c","text":"It is too broad: it will include healthy people.","feedback":"The opposite: it excludes people who are ill.","misconception":"cd-narrow-broad"},{"id":"d","text":"It is perfect: stricter is always more accurate.","feedback":"Strict definitions improve specificity but lose cases and can hide the outbreak's true size.","misconception":"cd-more-better"}],"explanation":"Too many criteria drop real cases (low sensitivity). Too few let non-cases in (low specificity).","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-cd-1","hint":"Ask: who would this definition leave out, or let in by mistake?"},{"id":"q-cd-2","module":"lab","concept":"case-definition","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Why do investigators include person, place, and time in a case definition, not just symptoms?","options":[{"id":"a","text":"Because symptoms are unimportant.","feedback":"Symptoms matter. They work together with person, place, and time.","misconception":"cd-more-better"},{"id":"b","text":"Because only place matters in outbreaks.","feedback":"All of person, place, and time help separate outbreak cases from background illness.","misconception":"cd-narrow-broad"},{"id":"c","text":"Because many illnesses share symptoms. Place and time link cases to the same outbreak.","feedback":"Yes: a bug can cause the same symptoms any day, so time and place focus on this outbreak.","correct":true},{"id":"d","text":"To make the definition longer and more official.","feedback":"Length does not improve accuracy. Each element has a job.","misconception":"cd-more-better"}],"explanation":"Time, place, person, and symptoms together tie cases to the outbreak instead of everyday illness.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-cd-2p","hint":"Think about what makes these cases different from everyday illness."},{"id":"q-cd-2p","module":"lab","concept":"case-definition","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Stomach illness is common all year. Which addition best helps separate outbreak cases from ordinary background illness?","options":[{"id":"a","text":"Add the person's favorite food.","feedback":"Favorite foods are not a case criterion. Exposures are studied after cases are defined.","misconception":"cd-more-better"},{"id":"b","text":"Limit to people who got sick during the recent period and were linked to the area of concern.","feedback":"Yes: time and place narrow the case to this outbreak.","correct":true},{"id":"c","text":"Remove all symptoms from the definition.","feedback":"Without symptoms you cannot tell stomach illness from anything else.","misconception":"cd-more-better"},{"id":"d","text":"Count only the people who live farthest from the area.","feedback":"That moves away from the likely source.","misconception":"cd-narrow-broad"}],"explanation":"Because background illness is always happening, time and place focus the definition on the outbreak.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-cd-2","hint":"Think about what makes these cases different from everyday illness."},{"id":"q-epi-1","module":"lab","concept":"epi-curves","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"An epidemic curve shows one sharp peak with most cases within about 3 days, then almost none. What does this shape suggest?","options":[{"id":"a","text":"The outbreak is still growing.","feedback":"A sharp peak that drops fast means exposure has ended.","misconception":"epi-shape-confusion"},{"id":"b","text":"A point source: many people were exposed at about the same time, such as one meal or event.","feedback":"Yes: one narrow peak means a single, brief exposure.","correct":true},{"id":"c","text":"A continuous source: people were exposed over many days.","feedback":"A continuous source gives a long plateau, not one sharp peak.","misconception":"epi-shape-confusion"},{"id":"d","text":"Person-to-person spread in waves.","feedback":"Waves show repeated peaks about one incubation period apart.","misconception":"epi-shape-confusion"}],"explanation":"Point source: one sharp peak. Continuous source: a long plateau. Propagated (person-to-person): successive waves about one incubation period apart.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-epi-1p","hint":"Look at how wide the peak is."},{"id":"q-epi-1p","module":"lab","concept":"epi-curves","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"An epi curve rises quickly, then stays high for about two weeks before declining slowly. What does this shape suggest?","options":[{"id":"a","text":"A continuous source: people kept being exposed, such as contaminated water or a pool.","feedback":"Right: the plateau reflects ongoing exposure until the source is removed.","correct":true},{"id":"b","text":"A point source from a single meal.","feedback":"A single meal makes a narrow peak that ends within a few incubation periods.","misconception":"epi-shape-confusion"},{"id":"c","text":"Person-to-person spread in waves.","feedback":"Waves show distinct repeated peaks.","misconception":"epi-shape-confusion"},{"id":"d","text":"A data error.","feedback":"A broad plateau is a normal pattern for a continuing source.","misconception":"epi-shape-confusion"}],"explanation":"The shape of the curve reflects how long people were exposed.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-epi-1","hint":"Look at how wide the peak is."},{"id":"q-epi-2","module":"lab","concept":"epi-curves","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"An epi curve shows a small first peak, then a bigger peak about three days later, then a third. What is the most likely explanation?","options":[{"id":"a","text":"Reporting delay only.","feedback":"Delay shifts the curve; it does not create several separate peaks.","misconception":"epi-shape-confusion"},{"id":"b","text":"Propagated spread: each wave of cases infects the next, one incubation period later.","feedback":"Yes: repeating waves, spaced by about one incubation period, point to person-to-person spread.","correct":true},{"id":"c","text":"A single meal at an event.","feedback":"That gives one peak, not repeated waves.","misconception":"epi-shape-confusion"},{"id":"d","text":"A continuous source with no pattern.","feedback":"A continuous source gives a plateau, not separate waves.","misconception":"epi-shape-confusion"}],"explanation":"Repeating waves, spaced about one incubation period apart, show that sick people are infecting others.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-epi-2p","hint":"Count the peaks and look at the gaps."},{"id":"q-epi-2p","module":"lab","concept":"epi-curves","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A curve for a nursing home shows waves of illness each about 2 to 3 days apart. Which transmission type fits best?","options":[{"id":"a","text":"Propagated: person-to-person spread through the facility.","feedback":"Right: waves spaced like the incubation period show spread from case to case.","correct":true},{"id":"b","text":"Point source: one contaminated meal.","feedback":"One meal produces a single peak.","misconception":"epi-shape-confusion"},{"id":"c","text":"Continuous source: a contaminated water supply.","feedback":"A continuous source gives a plateau.","misconception":"epi-shape-confusion"},{"id":"d","text":"Not enough information at all.","feedback":"The shape itself is informative.","misconception":"epi-shape-confusion"}],"explanation":"Successive waves mean cases are generating more cases.","context":"lesson:lab-casedef-epicurve","seconds":40,"parallel":"q-epi-2","hint":"Count the peaks and look at the gaps."},{"id":"q-ar-1","module":"lab","concept":"attack-rate","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"At a picnic, 60 people ate the potato salad and 24 got sick. What is the attack rate for people who ate the potato salad?","options":[{"id":"a","text":"60%","feedback":"60 is the number exposed. Divide cases by that, not the other way around.","misconception":"ar-count-percent"},{"id":"b","text":"2.5%","feedback":"That divides 1 by 40. Use cases divided by people exposed.","misconception":"ar-count-percent"},{"id":"c","text":"40% (24 out of 60)","feedback":"Right: attack rate = ill among those exposed divided by everyone exposed.","correct":true},{"id":"d","text":"24%","feedback":"24 is the number of cases, not a percent. Divide by the number who ate it (60).","misconception":"ar-count-percent"}],"explanation":"Attack rate = number who became ill ÷ number at risk, shown as a percent. It is the proportion who got sick, not the count.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-ar-1p","hint":"Divide cases by the number of people who were at risk."},{"id":"q-ar-1p","module":"lab","concept":"attack-rate","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"In one school class of 25 students, 10 became ill during an outbreak. What is the attack rate for the class?","options":[{"id":"a","text":"250%","feedback":"A rate cannot exceed 100%. Divide cases by people at risk.","misconception":"ar-count-percent"},{"id":"b","text":"40% (10 out of 25)","feedback":"Right: cases divided by everyone at risk.","correct":true},{"id":"c","text":"10%","feedback":"10 is the count of cases, not a rate.","misconception":"ar-count-percent"},{"id":"d","text":"25%","feedback":"25 is the class size.","misconception":"ar-count-percent"}],"explanation":"Divide the number ill by the number exposed.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-ar-1","hint":"Divide cases by the number of people who were at risk."},{"id":"q-rr-1","module":"lab","concept":"relative-risk","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"The attack rate is 50% for people who ate the chicken and 5% for people who did not. What is the relative risk and what does it mean?","options":[{"id":"a","text":"RR = 0.1: people who ate chicken were less likely to get sick.","feedback":"That divides the wrong way around (unexposed over exposed).","misconception":"rr-inverted"},{"id":"b","text":"RR = 1: no association.","feedback":"An RR of 1 means equal risk. Here the exposed had a much higher attack rate.","misconception":"rr-inverted"},{"id":"c","text":"RR = 10: people who ate the chicken were 10 times as likely to get sick.","feedback":"Yes: relative risk compares the attack rate in the exposed to the unexposed. 50 ÷ 5 = 10.","correct":true},{"id":"d","text":"RR = 45: the difference between 50% and 5%.","feedback":"That subtracts. Relative risk divides the two attack rates.","misconception":"rr-difference"}],"explanation":"Relative risk = attack rate in the exposed ÷ attack rate in the unexposed. Values above 1 suggest the exposure raises risk; near 1 means little association.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-rr-1p","hint":"Put the exposed attack rate on top."},{"id":"q-rr-1p","module":"lab","concept":"relative-risk","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"In a survey, the attack rate was 30% among people who drank the lemonade and 6% among those who did not. What is the relative risk?","options":[{"id":"a","text":"1: no association.","feedback":"An RR near 1 would mean equal risk; this is far from 1.","misconception":"rr-inverted"},{"id":"b","text":"5: the drinkers were 5 times as likely to get sick.","feedback":"Right: 30 ÷ 6 = 5.","correct":true},{"id":"c","text":"24: the difference in attack rates.","feedback":"That subtracts. Divide to get relative risk.","misconception":"rr-difference"},{"id":"d","text":"0.2: drinkers were less likely to get ill.","feedback":"That divides the wrong way around.","misconception":"rr-inverted"}],"explanation":"Divide, do not subtract: exposed attack rate over unexposed.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-rr-1","hint":"Put the exposed attack rate on top."},{"id":"q-conf-1","module":"lab","concept":"confounding","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"In an outbreak, people who went to the festival have 2 times the illness of those who did not. But nearly all the sick people live in one neighborhood, and festival-goers are more common there. What is going on?","options":[{"id":"a","text":"Confounding: neighborhood is linked to both festival attendance and illness, so the festival may only look related.","feedback":"Yes: a third factor that goes with both the exposure and the illness can create a false link.","correct":true},{"id":"b","text":"The festival is certainly the cause because the RR is high.","feedback":"A high RR is not proof. A confounder can create the same pattern.","misconception":"conf-rr-proves"},{"id":"c","text":"The data must be wrong.","feedback":"The data may be right. The link is just not what it seems.","misconception":"conf-rr-proves"},{"id":"d","text":"Neighborhood does not matter in outbreaks.","feedback":"It matters a lot: place can be a confounder.","misconception":"conf-ignore-third"}],"explanation":"A confounder is linked to both the exposure and the outcome and can make a false association (or hide a real one). Checking within groups (stratifying) can reveal it.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-conf-1p","hint":"Is there something that goes with both the exposure and the illness?"},{"id":"q-conf-1p","module":"lab","concept":"confounding","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"A study finds that people who carry lighters get lung cancer more often. What best explains this?","options":[{"id":"a","text":"Lighters cause lung cancer.","feedback":"A lighter is a marker of smoking, not a cause.","misconception":"conf-rr-proves"},{"id":"b","text":"Lung cancer causes people to buy lighters.","feedback":"That is unlikely. The common cause is smoking.","misconception":"conf-rr-proves"},{"id":"c","text":"It is just chance and cannot be explained.","feedback":"There is a straightforward third factor.","misconception":"conf-ignore-third"},{"id":"d","text":"Confounding: smoking leads people both to carry lighters and to develop lung cancer.","feedback":"Right: carrying a lighter does not cause cancer; a third factor explains both.","correct":true}],"explanation":"A third factor connected to both exposure and illness can fake a link.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-conf-1","hint":"Is there something that goes with both the exposure and the illness?"},{"id":"q-conf-2","module":"lab","concept":"confounding","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"How can an investigator check whether neighborhood is confounding the festival-illness link?","options":[{"id":"a","text":"Compare festival-goers and non-goers within each neighborhood separately.","feedback":"Yes: stratifying by the confounder removes its influence. If the link vanishes within neighborhoods, it was confounding.","correct":true},{"id":"b","text":"Ignore neighborhood and use more people overall.","feedback":"More people does not remove confounding.","misconception":"conf-ignore-third"},{"id":"c","text":"Trust the highest relative risk.","feedback":"A high RR can be produced by confounding.","misconception":"conf-rr-proves"},{"id":"d","text":"Remove the cases from the data.","feedback":"Deleting cases biases the results.","misconception":"conf-ignore-third"}],"explanation":"Stratify by the suspected confounder. If the association disappears within strata, the confounder explains it.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-conf-2p","hint":"Look inside each group."},{"id":"q-conf-2p","module":"lab","concept":"confounding","type":"mc","difficulty":1,"trigger":"lesson-check","prompt":"Cases of heat-related illness are higher in neighborhoods with more ice cream sales. How could you test whether summer weather is confounding?","options":[{"id":"a","text":"Stop selling ice cream.","feedback":"That does not test the cause.","misconception":"conf-ignore-third"},{"id":"b","text":"Add more neighborhoods without any other change.","feedback":"More data does not remove the confounder.","misconception":"conf-ignore-third"},{"id":"c","text":"Assume the ice cream is the cause.","feedback":"The link may be due to heat.","misconception":"conf-rr-proves"},{"id":"d","text":"Compare ice cream sales and illness separately on hot days and on cool days.","feedback":"Right: comparing within levels of the confounder (temperature) tests whether the link persists.","correct":true}],"explanation":"Compare within groups that share the confounder.","context":"lesson:lab-attack-rr-confounding","seconds":40,"parallel":"q-conf-2","hint":"Look inside each group."}]`),r=e({default:()=>i}),i=JSON.parse(`[{"id":"q-lab-alert","module":"lab","concept":"outbreak-baseline","type":"mc","difficulty":2,"trigger":"sim-alert","prompt":"Riverton ERs usually see about 5 stomach-illness visits a day. Today there were 17. What is the best first step?","options":[{"id":"a","text":"Compare against the baseline over several days and start an investigation: this is well above expected.","feedback":"Yes: an outbreak is more cases than expected for that place and time. 17 against 5 is far outside normal variation.","correct":true},{"id":"b","text":"Ignore it. Some days are always busy.","feedback":"Some day-to-day variation is normal, but 17 vs. 5 is far beyond it.","misconception":"alert-ignore"},{"id":"c","text":"Announce the source immediately.","feedback":"You cannot name a source before collecting evidence.","misconception":"alert-jump"},{"id":"d","text":"Wait for the monthly report.","feedback":"Waiting lets an outbreak grow. Surveillance exists for early detection.","misconception":"alert-ignore"}],"explanation":"An outbreak is more cases than expected in a place and time. You decide by comparing with the normal baseline.","context":"sim:lab","seconds":40,"hint":"Compare today to what is normal."},{"id":"q-lab-sample","module":"lab","concept":"sample-size","type":"mc","difficulty":2,"trigger":"sim-sample","prompt":"You interviewed 6 sick people and 5 ate at the diner. A teammate says the diner is definitely the source. What is the best response?","options":[{"id":"a","text":"Six interviews is a small sample; results can change a lot with different people, so get more data and a comparison group.","feedback":"Right: small samples vary widely. Resampling shows how much the answer can move.","correct":true},{"id":"b","text":"Agree: 5 of 6 is nearly all of them.","feedback":"Without a comparison group, you do not know how many healthy people also ate there.","misconception":"sample-small-ok"},{"id":"c","text":"Stop investigating: the source is found.","feedback":"Stopping early on thin evidence risks the wrong source.","misconception":"sample-small-ok"},{"id":"d","text":"Interview only people who ate at the diner.","feedback":"That biases the sample toward your guess.","misconception":"sample-small-ok"}],"explanation":"Small samples bounce around by chance. A comparison group and a larger sample make results more trustworthy.","context":"sim:lab","seconds":40,"hint":"Ask how much the numbers would change with different people."},{"id":"q-lab-bias","module":"lab","concept":"bias","type":"mc","difficulty":2,"trigger":"sim-bias","prompt":"People who got sick may remember and report foods more carefully than healthy people, and may forget details after many days. Which problem does this describe?","options":[{"id":"a","text":"Recall bias: memory differs between groups and fades with time.","feedback":"Yes: recall bias can make exposures look more or less linked to illness.","correct":true},{"id":"b","text":"Confounding by neighborhood.","feedback":"Confounding is a third factor linked to both exposure and illness, not memory.","misconception":"bias-mix"},{"id":"c","text":"A larger attack rate.","feedback":"Attack rate is a calculation, not a source of error in answers.","misconception":"bias-mix"},{"id":"d","text":"Reporting delay.","feedback":"Delay is when data arrives, not how well people remember.","misconception":"bias-mix"}],"explanation":"Recall bias comes from imperfect or different memory. It grows with time since the exposure.","context":"sim:lab","seconds":40},{"id":"q-lab-limit-inv","module":"lab","concept":"bias","type":"mc","difficulty":2,"trigger":"sim-limits","prompt":"Which of these is a limitation of the investigation (not the simulation model)?","options":[{"id":"a","text":"Many sick people were never tested, so the line list undercounts cases.","feedback":"Right: underreporting limits how much you can say about the true outbreak.","correct":true},{"id":"b","text":"The germ in this lab is fictional.","feedback":"That is a limitation of the simulation, not of the investigation.","misconception":"limit-mix"},{"id":"c","text":"The model leaves out genetic testing.","feedback":"That is a model limitation.","misconception":"limit-mix"},{"id":"d","text":"There are no limitations; the data is perfect.","feedback":"All investigations have limits: undercounting, memory error, small numbers, confounding.","misconception":"limit-none"}],"explanation":"Investigation limits include underreporting, recall bias, small samples, confounding, and the choice of comparison group.","context":"sim:lab","seconds":40},{"id":"q-lab-limit-model","module":"lab","concept":"models-limits","type":"mc","difficulty":2,"trigger":"sim-limits","prompt":"Which of these is a limitation of this simulation model (not of a real investigation)?","options":[{"id":"a","text":"The pathogen is fictional and the model leaves out genetic testing of cases.","feedback":"Right: a model simplifies. Knowing what it omits tells you how far to trust it.","correct":true},{"id":"b","text":"Sick people forget what they ate.","feedback":"That is a limit of real interviews, which the model represents on purpose.","misconception":"limit-mix"},{"id":"c","text":"The model is a perfect copy of a real city.","feedback":"Models are simplified. This one uses invented numbers.","misconception":"model-real"},{"id":"d","text":"Models never have limitations.","feedback":"Every model leaves things out.","misconception":"model-real"}],"explanation":"A model is a simplified version of reality. Good scientists name what a model leaves out.","context":"sim:lab","seconds":40},{"id":"q-lab-privacy","module":"lab","concept":"privacy-stigma","type":"mc","difficulty":2,"trigger":"sim-ethics","prompt":"The health department wants to tell the public about the outbreak. Which approach best protects privacy and avoids stigma?","options":[{"id":"a","text":"Share counts by broad area and describe the source and advice, without names, addresses, or blaming a group.","feedback":"Yes: share what people need to protect themselves while de-identifying cases and avoiding stigma.","correct":true},{"id":"b","text":"Publish a map with each case's street address.","feedback":"With few cases in a small neighborhood, addresses can identify individuals.","misconception":"privacy-publish-all"},{"id":"c","text":"Say that the outbreak is a problem with one neighborhood's residents.","feedback":"That stigmatizes a community. The source is a place or product, not the people.","misconception":"privacy-stigma"},{"id":"d","text":"Share nothing at all.","feedback":"People need information to protect themselves.","misconception":"privacy-publish-all"}],"explanation":"Public health balances the public's need to know with privacy. Small numbers in small areas can identify people.","context":"sim:lab","seconds":40},{"id":"q-lab-cf","module":"lab","concept":"interventions-counterfactual","type":"mc","difficulty":2,"trigger":"sim-counterfactual","prompt":"Your intervention started on day 9 and the outbreak shrank. How can you tell how many cases it really prevented?","options":[{"id":"a","text":"Compare with what would have happened without the intervention (a counterfactual).","feedback":"Yes: you cannot see the world where you did nothing, so the model compares the two.","correct":true},{"id":"b","text":"Count how many cases there were after the intervention.","feedback":"That ignores what would have happened anyway.","misconception":"cf-no-compare"},{"id":"c","text":"Assume the intervention caused every drop.","feedback":"Outbreaks rise and fall on their own too.","misconception":"cf-no-compare"},{"id":"d","text":"It cannot be estimated.","feedback":"A counterfactual comparison makes an estimate possible.","misconception":"cf-no-compare"}],"explanation":"A counterfactual is what would have happened without the action. Comparing it with the actual result estimates the effect.","context":"sim:lab","seconds":40},{"id":"q-lab-cer","module":"lab","concept":"confounding","type":"cer","difficulty":3,"trigger":"sim-conclusion","prompt":"Write your conclusion. Claim: what was the source and how did it spread? Evidence: which data support it (epi curve, map, attack rates, relative risk, lab or inspection results)? Reasoning: why does the evidence point to this source and not the other suspects (including the popular restaurant or the festival)?","explanation":"A strong conclusion names a source, cites specific numbers, and explains why alternatives (red herrings and confounders) were ruled out.","context":"sim:lab","rubric":[{"id":"claim","criterion":"States a clear source and mode of transmission."},{"id":"evidence","criterion":"Cites specific data such as attack rates, RR, curve shape, map, or lab/inspection results."},{"id":"reasoning","criterion":"Explains why the evidence supports the source and rules out alternatives, including confounding."},{"id":"limits","criterion":"Acknowledges at least one limitation (underreporting, recall bias, small numbers)."}],"sampleAnswer":"Claim: The outbreak came from the contaminated water supply after the main break in Old Town, and it spread through drinking tap water. Evidence: Reported cases cluster in Old Town on the spot map, and the epi curve shows a long plateau, which fits a continuing source. Among residents I surveyed, those who drank tap water had an attack rate of 48% compared with 6% for those who did not (RR about 8). Water samples from Old Town came back positive. Reasoning: The festival looked linked (RR about 2), but festival-goers are more common in Old Town, so neighborhood is a confounder. Within Old Town the festival RR was near 1. The diner had an RR near 1, so it was a red herring. Limitations: only a small share of cases were reported and my sample was small, so the numbers could change with different people.","required":true}]`),a=e({default:()=>ie}),ie=[{id:`q-ch-1`,module:`shared`,concept:`community-health`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`Which of these is an example of community (public) health work, rather than care for one patient?`,options:[{id:`a`,text:`A doctor prescribes antibiotics to one patient with strep throat.`,feedback:`That is individual medical care. It matters, but it treats one person at a time.`,misconception:`ch-individual-care`},{id:`b`,text:`The city tests drinking water and replaces lead pipes in one neighborhood.`,feedback:`Right: it protects everyone in the community at once by changing the conditions they share.`,correct:!0},{id:`c`,text:`A teenager gets a sports physical before the season.`,feedback:`A check-up helps one person. Community health looks at what protects whole groups.`,misconception:`ch-individual-care`},{id:`d`,text:`A store sells vitamins on sale.`,feedback:`Selling a product is not a coordinated effort to protect a population's health.`,misconception:`ch-products`}],explanation:`Community health works on the conditions and systems a whole group shares, such as water, air, food, and access to care, so many people are protected at once.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-ch-1p`,hint:`Ask: does this action protect a whole group, or help one person?`},{id:`q-ch-1p`,module:`shared`,concept:`community-health`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`A county health department runs a free vaccination clinic at a school and tracks vaccination rates by zip code. Why is this community health?`,options:[{id:`a`,text:`Because a nurse gives each student a shot.`,feedback:`The shots are individual care, but the tracking and outreach by zip code are what make it a population effort.`,misconception:`ch-individual-care`},{id:`b`,text:`Because it aims to raise protection across a whole population and uses data to find gaps.`,feedback:`Yes: the goal is the group's health, and zip-code data shows where protection is lowest.`,correct:!0},{id:`c`,text:`Because vaccines are sold in stores.`,feedback:`Where a product is sold is not what makes work public health.`,misconception:`ch-products`},{id:`d`,text:`Because it is free.`,feedback:`Cost matters for access, but the defining feature is working at the population level.`,misconception:`ch-individual-care`}],explanation:`Public health acts on groups and uses data to find who is left out, here zip codes with low vaccination coverage.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-ch-1`,hint:`What is the goal: one patient's recovery or the whole population's protection?`},{id:`q-ch-2`,module:`shared`,concept:`community-health`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`Two Riverton neighborhoods 3 miles apart have a 12-year life expectancy gap. Which explanation best fits a community-health view?`,options:[{id:`a`,text:`People in the poorer neighborhood simply make worse choices.`,feedback:`Choices matter, but they are shaped by what is available: food, safe places to be active, income, and care. Blaming individuals hides the conditions.`,misconception:`ch-blame-choices`},{id:`b`,text:`Differences in conditions such as income, housing, food, air, and access to care shape health.`,feedback:`Right: these social and environmental conditions, called determinants of health, explain much of such gaps.`,correct:!0},{id:`c`,text:`The gap is caused by genes alone.`,feedback:`Genes play a role, but they cannot explain large differences between nearby neighborhoods. Conditions do.`,misconception:`ch-genes-only`},{id:`d`,text:`The gap is random chance.`,feedback:`Gaps this large and consistent across years are not random; they follow patterns in conditions.`,misconception:`ch-random`}],explanation:`Where people live, work, and play shapes health. Large gaps between nearby neighborhoods usually reflect differences in these conditions.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-ch-2p`,hint:`Think about what is different between the two places, not about the people.`},{id:`q-ch-2p`,module:`shared`,concept:`community-health`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`Asthma in children is three times as common in homes near a highway as in homes far from it. Which explanation best fits a community-health view?`,options:[{id:`a`,text:`Families near the highway do not care about their children's health.`,feedback:`That blames people. Air pollution and housing conditions are far more likely causes.`,misconception:`ch-blame-choices`},{id:`b`,text:`Traffic pollution and older housing near the highway raise asthma risk.`,feedback:`Yes: exposure to polluted air is a condition of the place, not a personal failing.`,correct:!0},{id:`c`,text:`Asthma is inherited, so it only depends on family genes.`,feedback:`Genes matter, but the three-fold difference by location points to the environment.`,misconception:`ch-genes-only`},{id:`d`,text:`It is a coincidence.`,feedback:`A pattern this strong is unlikely to be coincidence; it should be investigated.`,misconception:`ch-random`}],explanation:`Place-based exposures such as air pollution can explain health gaps between groups.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-ch-2`,hint:`What is different about where these children live?`},{id:`q-pop-1`,module:`shared`,concept:`individual-vs-population`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`Which question is a population-health question?`,options:[{id:`a`,text:`Why does this patient's blood pressure stay high?`,feedback:`That asks about one person. A clinician would answer it with tests and treatment.`,misconception:`pop-one-person`},{id:`b`,text:`Why is high blood pressure more common in Eastside than in Hillcrest, and what could lower it for everyone there?`,feedback:`Right: it compares groups and looks for changes that could help the whole population.`,correct:!0},{id:`c`,text:`Should I take my medicine at night or in the morning?`,feedback:`That is a personal decision, not a population question.`,misconception:`pop-one-person`},{id:`d`,text:`How many pills are in this bottle?`,feedback:`This is a count, not a question about the health of a group.`,misconception:`pop-counts-only`}],explanation:`Population health asks how health is distributed across groups and what changes would improve it for many people.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-pop-1p`,hint:`Look for the choice that compares groups or aims to change things for many people.`},{id:`q-pop-1p`,module:`shared`,concept:`individual-vs-population`,type:`mc`,difficulty:1,trigger:`lesson-check`,prompt:`Which question is a population-health question?`,options:[{id:`a`,text:`Why did my grandmother's flu last two weeks?`,feedback:`That is about one person's illness.`,misconception:`pop-one-person`},{id:`b`,text:`Which Riverton neighborhoods have the lowest flu-shot rates, and how could we reach them?`,feedback:`Yes: it compares groups and plans action for the population.`,correct:!0},{id:`c`,text:`Is my cough a cold or the flu?`,feedback:`That is an individual diagnosis question.`,misconception:`pop-one-person`},{id:`d`,text:`What time does the clinic open?`,feedback:`Useful information, but not a question about the health of a group.`,misconception:`pop-counts-only`}],explanation:`Population health compares groups and looks for ways to improve health for many people.`,context:`lesson:orientation-community-health`,seconds:40,parallel:`q-pop-1`,hint:`Which one is about a group, not a single person?`}],ae=e({default:()=>oe}),oe=[{id:`q-wrap-cer`,module:`shared`,concept:`community-health`,type:`cer`,difficulty:3,trigger:`wrapup`,context:`sim:wrapup`,required:!0,prompt:`Write the executive summary of the Riverton Health Commission's annual report. Claim: what is Riverton's biggest health challenge, and what do you recommend? Evidence: use specific results from your City plan, the Town Hall, the outbreak investigation, and the Rumor Mill. Reasoning: connect determinants of health, equity, evidence together with community voice, and one limitation of what you did or what the models can show.`,explanation:`A strong executive summary makes one clear recommendation, backs it with specific results from more than one chapter, ties them together with ideas like determinants, equity, and trust, and admits what is uncertain.`,rubric:[{id:`claim`,criterion:`States the biggest challenge and a clear recommendation.`},{id:`evidence`,criterion:`Cites specific results from at least two chapters (City, Town Hall, Outbreak, Rumor Mill).`},{id:`connect`,criterion:`Connects ideas across chapters, such as determinants, equity, community voice, or trust.`},{id:`limits`,criterion:`Names a limitation or uncertainty.`}],sampleAnswer:`Claim: Riverton's biggest challenge is the 12-year life expectancy gap between Hillcrest and Eastside, and I recommend investing upstream in Eastside's conditions (care access, food, housing protections) together with the residents who live there. Evidence: In City, a plan centered on a clinic, health workers, and food access narrowed the gap by about 4 years over ten years, but a plan with many new amenities displaced nearly 10% of longtime residents. At the Town Hall, the Saturday session let a parent and an elder be heard, and adding housing protections kept displacement near zero. In the outbreak, interviewing only cases pointed at the popular diner, but comparing exposed and unexposed people showed the water supply, and trust determined how many people boiled their water. Reasoning: Together these show that health follows conditions, that benefits reach people only if they stay and trust the system, and that evidence from data and from residents both matter. A limitation is that the models are simplified and use invented numbers, so real effects would differ.`}],se=e({blocks:()=>u,concepts:()=>l,default:()=>ce,id:()=>o,minutes:()=>3,module:()=>c,title:()=>s}),o=`city-equity`,s=`Health equity vs. equality`,c=`city`,l=[`equity-equality`],u=[{type:`hook`,text:`The city has $4 million. Should each of eight neighborhoods get $500,000, or should the money go where the need is greatest?`},{type:`explain`,chunks:[{text:`**Equality** means everyone gets the same share. **Health equity** means everyone has a fair chance to be as healthy as possible, which sometimes means giving more to those with more needs.`,terms:[`health equity`]},{text:`The **health equity gap** in Riverton is the difference in life expectancy between the best-off and worst-off neighborhoods. A plan that is equal but not equitable can leave that gap in place.`,terms:[`health equity gap`]}]},{type:`visual`,title:`Equal vs. equitable`,steps:[{caption:`Equality: every neighborhood gets the same amount.`,nodes:[`Same for everyone`],active:[0]},{caption:`But neighborhoods start in different places.`,nodes:[`Same for everyone`,`Different starting points`],active:[1]},{caption:`Equity: put more where the need and gap are greatest, so outcomes become fairer.`,nodes:[`Different starting points`,`More where need is greatest`,`Smaller gap`],active:[1,2]}]},{type:`worked`,title:`Worked example: split the money`,steps:[`Situation: Eight neighborhoods, one with a life expectancy 12 years lower.`,`Equality: $500,000 each. The low-income neighborhood stays far behind.`,`Equity: put most of the money in the worst-off neighborhood.`,`Check: did the gap shrink? That is the test of whether it was equitable.`]},{type:`guided`,questionId:`q-eq-1p`},{type:`check`,questionIds:[`q-eq-1`,`q-eq-2`]},{type:`summary`,cardId:`card-city-equity`,bullets:[`Equality means the same for everyone.`,`Equity means giving what each group needs for a fair chance at good health.`,`Equal shares can leave gaps in place.`,`The test: does the gap between neighborhoods get smaller?`]}],ce={id:o,title:s,module:c,concepts:l,minutes:3,blocks:u},le=e({blocks:()=>h,concepts:()=>m,default:()=>ue,id:()=>d,minutes:()=>3,module:()=>p,title:()=>f}),d=`city-sdoh`,f=`Social determinants of health`,p=`city`,m=[`sdoh`],h=[{type:`hook`,text:`Hillcrest and Eastside are three miles apart. Life expectancy differs by twelve years. What is different about the two places?`,map:[`hillcrest`,`eastside`]},{type:`explain`,chunks:[{text:`**Social determinants of health** are the conditions where people are born, live, learn, work, and play. They shape health more than medical care alone.`,terms:[`determinants of health`]},{text:`There are five domains: **economic stability**, **education**, **health care access**, **neighborhood and built environment**, and **social and community context**. In Riverton’s City model you will see them as ten conditions that you can change.`,terms:[`health equity`]}]},{type:`visual`,title:`From conditions to health`,steps:[{caption:`Start with a condition of a place: for example, no full-service grocery nearby.`,nodes:[`Condition: food access`],active:[0]},{caption:`The condition shapes what people can easily do or eat.`,nodes:[`Condition: food access`,`Behavior: diet`],active:[0,1]},{caption:`Over years, behaviors and exposures add up to health outcomes.`,nodes:[`Condition: food access`,`Behavior: diet`,`Outcome: diabetes`],active:[0,1,2]}]},{type:`worked`,title:`Worked example: which domain?`,steps:[`Situation: Children near a busy highway breathe more polluted air.`,`Ask: is this about money, school, care, the place, or community?`,`It is about the place, so the domain is the neighborhood and built environment.`,`Because it is a condition and not a personal choice, the solution is also at the community level: filters, trees, cleaner emissions.`]},{type:`guided`,questionId:`q-sdoh-1p`},{type:`check`,questionIds:[`q-sdoh-1`,`q-sdoh-2`,`q-sdoh-3`]},{type:`summary`,cardId:`card-city-sdoh`,bullets:[`Social determinants are the conditions where people live, learn, work, and play.`,`There are five domains: economic, education, health care, neighborhood, community.`,`Gaps between nearby neighborhoods usually come from differences in conditions.`,`In the City model, interventions change conditions first, then behaviors, then outcomes.`]}],ue={id:d,title:f,module:p,concepts:m,minutes:3,blocks:h},de=e({blocks:()=>b,concepts:()=>y,default:()=>fe,id:()=>g,minutes:()=>3,module:()=>v,title:()=>_}),g=`city-upstream`,_=`Upstream vs. downstream, and levels of prevention`,v=`city`,y=[`upstream-downstream`,`prevention-levels`],b=[{type:`hook`,text:`A boy keeps falling into a river. You can keep rescuing him downstream, or you can walk upstream and find out who is pushing people in. Which saves more people?`},{type:`explain`,chunks:[{text:`**Downstream** actions respond after harm, such as ER care. **Upstream** actions change the causes, such as housing, clean air, and income. Upstream work usually takes longer to show results but prevents more illness.`,terms:[`upstream`]},{text:`**Primary prevention** stops a problem before it starts (vaccines). **Secondary prevention** catches it early (screenings). **Tertiary prevention** limits harm from an existing problem (managing diabetes).`,terms:[`prevention`]}]},{type:`visual`,title:`Three levels of prevention`,steps:[{caption:`Primary: nobody is sick yet. Stop the problem from starting.`,nodes:[`Healthy`,`Primary: vaccines, clean water`],active:[1]},{caption:`Secondary: the illness is just starting. Catch it early.`,nodes:[`Early illness`,`Secondary: screenings`],active:[1]},{caption:`Tertiary: the illness is established. Limit the harm.`,nodes:[`Established illness`,`Tertiary: treatment, rehab`],active:[1]}]},{type:`worked`,title:`Worked example: classify the program`,steps:[`Situation: Free blood pressure checks at a community event.`,`Is anyone sick yet? Some people may have high blood pressure and not know it.`,`The program finds it early, so it is secondary prevention.`,`It is more upstream than ER care, but less upstream than raising incomes.`]},{type:`guided`,questionId:`q-ud-1p`},{type:`check`,questionIds:[`q-ud-1`,`q-pl-1`,`q-pl-2`]},{type:`summary`,cardId:`card-city-upstream`,bullets:[`Upstream actions change causes. Downstream actions respond to harm.`,`Primary prevention stops problems before they start.`,`Secondary prevention finds them early.`,`Tertiary prevention limits harm from existing problems.`]}],fe={id:g,title:_,module:v,concepts:y,minutes:3,blocks:b},pe=e({blocks:()=>w,concepts:()=>C,default:()=>me,id:()=>x,minutes:()=>3,module:()=>`lab`,title:()=>S}),x=`lab-attack-rr-confounding`,S=`Attack rate, relative risk, and confounding`,C=[`attack-rate`,`relative-risk`,`confounding`],w=[{type:`hook`,text:`Everyone who ate the potato salad got sick. But so did a lot of people who didn't. How do you decide which food is the real culprit?`},{type:`explain`,chunks:[{text:`The **attack rate** is the proportion of people at risk who became ill: cases ÷ people exposed. Compare the attack rate in people who had an exposure to the attack rate in people who did not.`,terms:[`attack rate`]},{text:`**Relative risk** (RR) = attack rate in the exposed ÷ attack rate in the unexposed. An RR far above 1 points to a likely culprit. But beware **confounding**: a third factor linked to both the exposure and the illness can create a fake link.`,terms:[`relative risk`,`confounding`]}]},{type:`visual`,title:`Compare exposed and unexposed`,steps:[{caption:`Count who ate the food and who got sick in a 2×2 table.`,nodes:[`Ate it: 40 ill, 20 not ill`,`Did not eat it: 4 ill, 36 not ill`],active:[0,1]},{caption:`Attack rate in those who ate it: 40 ÷ 60 = 67%. In those who did not: 4 ÷ 40 = 10%.`,nodes:[`Exposed: 67%`,`Unexposed: 10%`],active:[0,1]},{caption:`Relative risk = 67% ÷ 10% ≈ 6.7. The food is a strong suspect, but check for confounders.`,nodes:[`RR ≈ 6.7`,`Check confounders`],active:[0,1]}]},{type:`worked`,title:`Worked example: a confounder`,steps:[`Situation: festival-goers have an RR of 2 for illness.`,`But nearly all the sick people live in Old Town, and Old Town residents are more likely to attend.`,`Compare festival-goers and non-goers inside Old Town.`,`If the RR within Old Town is near 1, then neighborhood (not the festival) explains the link: confounding.`]},{type:`guided`,questionId:`q-ar-1p`},{type:`check`,questionIds:[`q-ar-1`,`q-rr-1`,`q-conf-1`,`q-conf-2`]},{type:`summary`,cardId:`card-lab-attack-rr-confounding`,bullets:[`Attack rate = ill ÷ at risk.`,`Relative risk = exposed attack rate ÷ unexposed attack rate.`,`A high RR suggests a link; it does not prove cause.`,`A confounder is tied to both exposure and illness; compare within groups to check.`]}],me={id:x,title:S,module:`lab`,concepts:C,minutes:3,blocks:w},he=e({blocks:()=>O,concepts:()=>D,default:()=>ge,id:()=>T,minutes:()=>3,module:()=>`lab`,title:()=>E}),T=`lab-casedef-epicurve`,E=`Case definitions and epidemic curves`,D=[`case-definition`,`epi-curves`],O=[{type:`hook`,text:`If you count everyone with a stomach ache as a case, your outbreak might be ten times bigger than it really is. How should investigators decide who counts?`},{type:`explain`,chunks:[{text:`A **case definition** is a set of rules for who counts as a case: **person**, **place**, **time**, and **symptoms**. A broad definition finds more people but includes non-cases (low **specificity**). A narrow one is cleaner but misses real cases (low **sensitivity**).`,terms:[`case definition`]},{text:`An **epidemic curve** is a histogram of when people got sick. Its shape hints at the source: **point source** (one narrow peak), **continuous source** (a long plateau), or **propagated** spread (waves).`,terms:[`epidemic curve`]}]},{type:`visual`,title:`Three curve shapes`,steps:[{caption:`Point source: everyone exposed once, such as one meal. A single sharp peak.`,nodes:[`Single exposure`,`One sharp peak`],active:[0,1]},{caption:`Continuous source: exposure goes on, such as contaminated water. A long plateau.`,nodes:[`Ongoing exposure`,`Long plateau`],active:[0,1]},{caption:`Propagated: sick people infect others. Waves roughly one incubation period apart.`,nodes:[`First cases`,`Second wave`,`Third wave`],active:[0,1,2]}]},{type:`worked`,title:`Worked example: reading a curve`,steps:[`Situation: A curve rises over two days, peaks, and then nearly disappears within four days.`,`Ask: how many exposures could cause that? Probably one event.`,`Ask: does it show waves? No.`,`Conclusion: this looks like a point source. The investigator should ask what almost everyone shared at one time.`]},{type:`guided`,questionId:`q-cd-1p`},{type:`check`,questionIds:[`q-cd-1`,`q-cd-2`,`q-epi-1`,`q-epi-2`]},{type:`summary`,cardId:`card-lab-casedef-epicurve`,bullets:[`A case definition uses person, place, time, and symptoms.`,`Too broad lowers specificity; too narrow lowers sensitivity.`,`Point source: one peak. Continuous source: plateau. Propagated: waves.`,`Curve shape helps narrow down the source.`]}],ge={id:T,title:E,module:`lab`,concepts:D,minutes:3,blocks:O},k=e({blocks:()=>N,concepts:()=>M,default:()=>P,id:()=>A,minutes:()=>3,module:()=>`lab`,title:()=>j}),A=`lab-chain-surveillance`,j=`Chain of infection and surveillance`,M=[`chain-of-infection`,`surveillance`],N=[{type:`hook`,text:`On Monday, 5 people in Riverton got sick. By Friday, the health department knew about only 2 of them. What happened to the others?`},{type:`explain`,chunks:[{text:`Germs that cause outbreaks travel in a **chain of infection**: a germ lives in a **reservoir**, leaves the body, travels through a **vehicle** such as food or water, enters a new person, and finds a **susceptible host**. Break any link and the chain stops.`,terms:[`chain of infection`]},{text:`Health departments watch for outbreaks using **surveillance**: ongoing collection of illness data. But surveillance sees only the **tip of the iceberg**. Many people stay home or are never tested, and reports arrive days late.`,terms:[`surveillance`]}]},{type:`visual`,title:`The surveillance pyramid`,steps:[{caption:`Imagine 1,000 people become ill from one outbreak.`,nodes:[`1,000 ill`],active:[0]},{caption:`Only some seek medical care.`,nodes:[`1,000 ill`,`250 seek care`],active:[1]},{caption:`Only some of those are tested at a lab.`,nodes:[`1,000 ill`,`250 seek care`,`125 tested`],active:[2]},{caption:`Only some test results are reported, and days later. The department sees about 50 of 1,000.`,nodes:[`1,000 ill`,`250 seek care`,`125 tested`,`50 reported`],active:[3]}]},{type:`worked`,title:`Worked example: where is the chain broken?`,steps:[`Situation: A pool is contaminated and 30 swimmers get sick.`,`Reservoir: a sick swimmer. Vehicle: the pool water. Host: other swimmers.`,`Where can we break the chain? Close the pool (stop the vehicle) or disinfect the water.`,`Notice that treating each sick swimmer does not stop new people from getting sick.`]},{type:`guided`,questionId:`q-coi-1p`},{type:`check`,questionIds:[`q-coi-1`,`q-surv-1`,`q-surv-2`]},{type:`summary`,cardId:`card-lab-chain-surveillance`,bullets:[`The chain of infection has six links; break any one to stop spread.`,`The vehicle carries the germ from the reservoir to new hosts.`,`Surveillance sees only part of the illness: the tip of the pyramid.`,`Reports lag behind illness, so the newest days look low.`]}],P={id:A,title:j,module:`lab`,concepts:M,minutes:3,blocks:N},F=e({blocks:()=>B,concepts:()=>z,default:()=>_e,id:()=>I,minutes:()=>3,module:()=>R,title:()=>L}),I=`orientation-community-health`,L=`What is community health?`,R=`shared`,z=[`community-health`,`individual-vs-population`],B=[{type:`hook`,text:`Two Riverton neighborhoods are about 3 miles apart. In one, people live to 82 on average. In the other, 70. What could possibly explain 12 years?`,map:[`hillcrest`,`eastside`]},{type:`explain`,chunks:[{text:`**Public health** protects and improves the health of whole groups of people, called **populations**. A doctor helps the patient in the room. A health department asks who is *not* in the room, and why.`,terms:[`public health`,`population`]},{text:`Community health works on the **conditions** people share: clean water, safe places to be active, nearby food, and access to care. These are called **determinants of health**.`,terms:[`determinants of health`]}]},{type:`visual`,title:`From conditions to health`,steps:[{caption:`People live in places with different conditions.`,nodes:[`Conditions (water, air, food, income, care)`],active:[0]},{caption:`Conditions shape what is easy or hard to do each day.`,nodes:[`Conditions`,`Daily habits & exposures`],active:[0,1]},{caption:`Over years, habits and exposures add up to health outcomes.`,nodes:[`Conditions`,`Daily habits & exposures`,`Health outcomes`],active:[0,1,2]},{caption:`Public health changes the first box, so the whole chain shifts for everyone.`,nodes:[`Conditions`,`Daily habits & exposures`,`Health outcomes`],active:[0]}]},{type:`worked`,title:`Worked example: Is it individual care or community health?`,steps:[`Situation: A nurse treats a child's asthma attack in the ER.`,`Ask: Who is helped? One child.`,`Now compare: The city adds filters and a tree buffer between the highway and homes.`,`Ask: Who is helped? Every child who lives nearby, including ones who never go to the ER.`,`Conclusion: The first is individual care. The second changes a shared condition, so it is community health.`]},{type:`guided`,questionId:`q-ch-1p`},{type:`check`,questionIds:[`q-ch-1`,`q-ch-2`,`q-pop-1`]},{type:`summary`,cardId:`card-orientation`,bullets:[`Public health protects whole populations, not just one patient at a time.`,`Health is shaped by conditions people share: water, air, food, income, and access to care.`,`Large gaps between nearby neighborhoods point to differences in conditions, not in character.`,`Population questions compare groups and ask what would help many people.`]}],_e={id:I,title:L,module:R,concepts:z,minutes:3,blocks:B},ve=e({blocks:()=>G,concepts:()=>W,default:()=>ye,id:()=>V,minutes:()=>4,module:()=>U,title:()=>H}),V=`xr-decision-stakeholders`,H=`Making a community decision`,U=`crossroads`,W=[`decision-model`,`stakeholders`,`engagement-equity`],G=[{type:`hook`,text:`A city offers $2 million to fix a vacant lot in a neighborhood with a 12-year life expectancy gap. The room where it is decided is half empty. Who is missing, and does it matter?`},{type:`explain`,chunks:[{text:`Community health decisions follow a **decision model**: define the problem with data, identify who is affected, listen to the community, consider evidence-based options, weigh equity and trade-offs, decide, and evaluate.`,terms:[`decision model`]},{text:`A **stakeholder** is anyone affected by a decision or able to influence it. **Equity of participation** means removing barriers like work schedules, childcare, language, and transportation so the people most affected can take part. How and when you ask decides who answers.`,terms:[`stakeholder`]}]},{type:`visual`,title:`The decision model`,steps:[{caption:`Start with the problem, described with data.`,nodes:[`Define the problem`],active:[0]},{caption:`Then find out who is affected and listen to them.`,nodes:[`Define the problem`,`Who is affected? Listen`],active:[1]},{caption:`Weigh the options, with equity and trade-offs in view.`,nodes:[`Define the problem`,`Who is affected? Listen`,`Options, equity, trade-offs`],active:[2]},{caption:`Decide, then evaluate and learn.`,nodes:[`Options, equity, trade-offs`,`Decide`,`Evaluate`],active:[1,2]}]},{type:`worked`,title:`Worked example: who is at the table?`,steps:[`Situation: A city holds one listening session at 6 p.m. on a Tuesday downtown.`,`Ask: who can come? People with flexible jobs, cars, and no need for childcare.`,`Ask: who cannot? Shift workers, parents with young children, people without cars.`,`Change the plan: hold it on a weekend in the neighborhood, with childcare and interpreters.`]},{type:`guided`,questionId:`q-xdm-1p`},{type:`check`,questionIds:[`q-xdm-1`,`q-stk-1`,`q-eng-1`]},{type:`summary`,cardId:`card-xr-decision-stakeholders`,bullets:[`The decision model starts with the problem, defined with data.`,`Stakeholders are anyone affected or able to influence a decision.`,`Listening is only fair if the people most affected can take part.`,`How and when you ask decides who answers.`]}],ye={id:V,title:H,module:U,concepts:W,minutes:4,blocks:G},be=e({blocks:()=>X,concepts:()=>Y,default:()=>xe,id:()=>K,minutes:()=>2,module:()=>J,title:()=>q}),K=`xr-misinfo`,q=`Rumors, sources, and trusted voices`,J=`crossroads`,Y=[`misinformation`,`trusted-messengers`],X=[{type:`hook`,text:`A post says the boil-water notice is a hoax. It has 4,000 shares. Should you believe it?`},{type:`explain`,chunks:[{text:`**Misinformation** spreads fast, especially when people already distrust official sources. **Lateral reading** means leaving the post and checking what other reliable sources say about the claim and its source.`,terms:[`misinformation`]},{text:`Facts alone do not always change minds. **Trusted messengers**, such as faith leaders, elders, coaches, and bilingual neighbors, make accurate information believable.`,terms:[`trusted messenger`]}]},{type:`visual`,title:`Two ways to check`,steps:[{caption:`Vertical reading: you stay on the post and study it. It looks convincing.`,nodes:[`Read the post closely`],active:[0]},{caption:`Lateral reading: you open new tabs and search the claim and the source.`,nodes:[`Read the post closely`,`Open new tabs and check others`],active:[1]},{caption:`What reliable sources say tells you more than what the post says about itself.`,nodes:[`Open new tabs and check others`,`Compare with trusted sources`],active:[1]}]},{type:`worked`,title:`Worked example: a rumor about a clinic`,steps:[`Situation: A message says the clinic is making people sick.`,`Lateral step: search the clinic's name and read what the health department says.`,`Finding: sick people go to clinics, so clinics see many ill people. That is a correlation, not proof of cause.`,`Reply: acknowledge worry, share the finding, and ask a trusted neighbor to pass it on.`]},{type:`guided`,questionId:`q-mis-1p`},{type:`check`,questionIds:[`q-mis-1`,`q-tm-1`]},{type:`summary`,cardId:`card-xr-misinfo`,bullets:[`Do not judge a post by how popular it is.`,`Lateral reading: leave the page and check what others say.`,`Trusted messengers make accurate information believable.`,`Reach people in the languages they use.`]}],xe={id:K,title:q,module:J,concepts:Y,minutes:2,blocks:X},Z=e=>Object.values(e).map(e=>e.default),Se=Object.assign({"../content/shared/questions/city.json":t,"../content/shared/questions/crossroads.json":te,"../content/shared/questions/lab-lessons.json":ne,"../content/shared/questions/lab-sim.json":r,"../content/shared/questions/orientation.json":a,"../content/shared/questions/wrapup.json":ae}),Ce=Object.assign({"../content/shared/lessons/city-equity.json":se,"../content/shared/lessons/city-sdoh.json":le,"../content/shared/lessons/city-upstream.json":de,"../content/shared/lessons/lab-attack-rr-confounding.json":pe,"../content/shared/lessons/lab-casedef-epicurve.json":he,"../content/shared/lessons/lab-chain-surveillance.json":k,"../content/shared/lessons/orientation-community-health.json":F,"../content/shared/lessons/xr-decision-stakeholders.json":ve,"../content/shared/lessons/xr-misinfo.json":be}),Q=Z(Se).flat(),$=Z(Ce),we=e=>Q.find(t=>t.id===e),Te=e=>$.find(t=>t.id===e);export{we as i,Q as n,Te as r,$ as t};